package domain

import "strings"

// ValidMarketplaces defines the set of allowed Amazon marketplace codes
var ValidMarketplaces = map[string]bool{
	"US": true, // United States
	"CA": true, // Canada
	"MX": true, // Mexico
	"BR": true, // Brazil
	"UK": true, // United Kingdom
	"DE": true, // Germany
	"FR": true, // France
	"IT": true, // Italy
	"ES": true, // Spain
	"NL": true, // Netherlands
	"SE": true, // Sweden
	"PL": true, // Poland
	"TR": true, // Turkey
	"AE": true, // United Arab Emirates
	"SA": true, // Saudi Arabia
	"IN": true, // India
	"JP": true, // Japan
	"AU": true, // Australia
	"SG": true, // Singapore
}

// IsValidMarketplace checks if a marketplace code is valid
func IsValidMarketplace(marketplace string) bool {
	// Normalize to uppercase for case-insensitive comparison
	normalized := strings.ToUpper(strings.TrimSpace(marketplace))
	return ValidMarketplaces[normalized]
}

// NormalizeMarketplace returns the normalized (uppercase, trimmed) marketplace code
func NormalizeMarketplace(marketplace string) string {
	return strings.ToUpper(strings.TrimSpace(marketplace))
}

