package handler

import (
	"fmt"
	"time"

	"github.com/LittleAksMax/bids-service/internal/domain"
)

// ScheduleConfigRequest represents the JSON request body for creating/updating a schedule configuration
type ScheduleConfigRequest struct {
	UserID      string `json:"userId"`
	CampaignID  string `json:"campaignId"`
	Marketplace string `json:"marketplace"`
	Interval    int    `json:"interval"` // Interval in minutes (must be a multiple of 15)
}

// Validate checks if all required fields are present and valid
func (r *ScheduleConfigRequest) Validate(pollingInterval time.Duration) map[string]string {
	errors := make(map[string]string)

	if r.UserID == "" {
		errors["userId"] = "userId is required"
	}

	if r.CampaignID == "" {
		errors["campaignId"] = "campaignId is required"
	}

	if r.Marketplace == "" {
		errors["marketplace"] = "marketplace is required"
	} else if !domain.IsValidMarketplace(r.Marketplace) {
		errors["marketplace"] = "marketplace is not valid (must be a valid Amazon marketplace code like US, UK, DE, etc.)"
	} else {
		// Normalize the marketplace to uppercase
		r.Marketplace = domain.NormalizeMarketplace(r.Marketplace)
	}

	if r.Interval <= 0 {
		errors["interval"] = "interval is required and must be greater than 0"
	}

	if r.Interval > 0 && r.Interval%int(pollingInterval.Minutes()) != 0 {
		errors["interval"] = fmt.Sprintf("interval must be a multiple of polling interval (%d) minutes", int(pollingInterval.Minutes()))
	}

	return errors
}

// ToDomain converts the request DTO to a domain entity
func (r *ScheduleConfigRequest) ToDomain() *domain.ScheduleConfiguration {
	// Calculate DueAt by adding the interval to the current time
	now := time.Now()
	interval := time.Duration(r.Interval) * time.Minute
	dueAt := now.Add(interval)

	return &domain.ScheduleConfiguration{
		UserID:      r.UserID,
		CampaignID:  r.CampaignID,
		Marketplace: r.Marketplace,
		DueAt:       dueAt,
		LastUpdated: now,
		Interval:    interval,
	}
}

